import sys
import gzip
import collections
import math

def open_file(f):
    if f == '-': return sys.stdin
    if f.endswith('.gz'): return gzip.open(f, 'rt')
    return open(f, 'r')

def read_bed(f):
    records = []
    with open_file(f) as fp:
        for line in fp:
            if not line.strip() or line.startswith('#') or line.startswith('track') or line.startswith('browser'): continue
            parts = line.rstrip('\n').split('\t')
            if len(parts) >= 3:
                chrom = parts[0]
                start = int(parts[1])
                end = int(parts[2])
                records.append((chrom, start, end, parts))
    return records

def read_genome(f):
    genome = {}
    with open_file(f) as fp:
        for line in fp:
            if not line.strip(): continue
            parts = line.strip().split()
            genome[parts[0]] = int(parts[1])
    return genome

def format_record(parts):
    return '\t'.join(parts)

def cmd_intersect(args):
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument('-a', required=True)
    parser.add_argument('-b', nargs='+', required=True)
    parser.add_argument('-wa', action='store_true')
    parser.add_argument('-wb', action='store_true')
    parser.add_argument('-c', action='store_true')
    parser.add_argument('-v', action='store_true')
    parser.add_argument('-u', action='store_true')
    parser.add_argument('-wo', action='store_true')
    parser.add_argument('-f', type=float, default=1e-9)
    parser.add_argument('-r', action='store_true')
    parser.add_argument('-sorted', action='store_true')
    parser.add_argument('-names', nargs='*')

    parsed, unknown = parser.parse_known_args(args)

    # Read A
    A = read_bed(parsed.a)

    # Read all B
    B_records = []
    for i, b_file in enumerate(parsed.b):
        name = parsed.names[i] if parsed.names and i < len(parsed.names) else None
        for chrom, start, end, parts in read_bed(b_file):
            B_records.append((chrom, start, end, parts, name))

    B_by_chrom = collections.defaultdict(list)
    for rec in B_records:
        B_by_chrom[rec[0]].append(rec)

    for chrom in B_by_chrom:
        B_by_chrom[chrom].sort(key=lambda x: (x[1], x[2]))

    # Process A
    for chrom, a_start, a_end, a_parts in A:
        overlaps = []
        if chrom in B_by_chrom:
            # Naive overlap scan, B is sorted by start
            for b_chrom, b_start, b_end, b_parts, b_name in B_by_chrom[chrom]:
                if b_start >= a_end: break # Since B is sorted by start, no further B can overlap

                # Check overlap
                o_start = max(a_start, b_start)
                o_end = min(a_end, b_end)
                if o_start < o_end:
                    # check fraction
                    o_len = o_end - o_start
                    a_len = a_end - a_start
                    b_len = b_end - b_start
                    frac_a = o_len / a_len if a_len > 0 else 0
                    if frac_a >= parsed.f:
                        if parsed.r:
                            frac_b = o_len / b_len if b_len > 0 else 0
                            if frac_b >= parsed.f:
                                overlaps.append((o_start, o_end, b_parts, o_len, b_name))
                        else:
                            overlaps.append((o_start, o_end, b_parts, o_len, b_name))

        if parsed.c:
            print(f"{format_record(a_parts)}\t{len(overlaps)}")
        elif parsed.v:
            if not overlaps:
                print(format_record(a_parts))
        elif parsed.u:
            if overlaps:
                print(format_record(a_parts))
        else:
            if not overlaps: continue
            for o_start, o_end, b_parts, o_len, b_name in overlaps:
                out = []
                if parsed.wa and parsed.wb:
                    out.extend(a_parts)
                    out.extend(b_parts)
                elif parsed.wa:
                    out.extend(a_parts)
                elif parsed.wb:
                    out.extend(b_parts)
                elif parsed.wo:
                    out.extend(a_parts)
                    out.extend(b_parts)
                    out.append(str(o_len))
                else:
                    out = [chrom, str(o_start), str(o_end)]
                    if len(a_parts) > 3:
                        out.extend(a_parts[3:])
                print(format_record(out))

def main():
    if len(sys.argv) < 2: return
    cmd = sys.argv[1]
    args = sys.argv[2:]

    if cmd == 'intersect': cmd_intersect(args)
    # I will add other commands as needed

if __name__ == '__main__': main()
