def agg_op(vals, op):
    if op == 'count': return str(len(vals))
    if op == 'sum': return str(sum(float(v) for v in vals))
    if op == 'min': return str(min(float(v) for v in vals))
    if op == 'max': return str(max(float(v) for v in vals))
    if op == 'mean': return str(sum(float(v) for v in vals) / len(vals))
    if op == 'collapse': return ','.join(vals)
    return ','.join(vals)

def cmd_merge(args):
    parser = argparse.ArgumentParser()
    parser.add_argument('-i', required=True)
    parser.add_argument('-d', type=int, default=0)
    parser.add_argument('-c')
    parser.add_argument('-o')
    p, _ = parser.parse_known_args(args)

    recs_by_chrom = collections.defaultdict(list)
    for c, s, e, parts in read_bed(p.i):
        recs_by_chrom[c].append((s, e, parts))

    ops = p.o.split(',') if p.o else []
    cols = [int(x)-1 for x in p.c.split(',')] if p.c else []

    for c in recs_by_chrom:
        recs_by_chrom[c].sort(key=lambda x: x[0])

    for c, recs in recs_by_chrom.items():
        if not recs: continue
        cur_s, cur_e, cur_parts = recs[0]
        cur_cols = [[cur_parts[col]] if col < len(cur_parts) else ['.'] for col in cols]

        for s, e, parts in recs[1:]:
            if s <= cur_e + p.d:
                cur_e = max(cur_e, e)
                for i, col in enumerate(cols):
                    cur_cols[i].append(parts[col] if col < len(parts) else '.')
            else:
                out = [c, cur_s, cur_e]
                for i, op in enumerate(ops):
                    out.append(agg_op(cur_cols[i], op))
                print(format_record(out))
                cur_s, cur_e, cur_parts = s, e, parts
                cur_cols = [[cur_parts[col]] if col < len(cur_parts) else ['.'] for col in cols]

        out = [c, cur_s, cur_e]
        for i, op in enumerate(ops):
            out.append(agg_op(cur_cols[i], op))
        print(format_record(out))

def cmd_closest(args):
    parser = argparse.ArgumentParser()
