        B_by_chrom[c].append((s, e, parts))
    for c in B_by_chrom:
        B_by_chrom[c].sort(key=lambda x: x[0])

    # Get arbitrary b_parts to know column count for empty results
    b_len = 0
    for c in B_by_chrom:
        if B_by_chrom[c]:
            b_len = len(B_by_chrom[c][0][2])
            break
    empty_b = ['.'] * b_len if b_len > 0 else ['.', '-1', '-1']
    if empty_b[:3] == ['.', '.', '.']:
        empty_b[1] = '-1'
        empty_b[2] = '-1'

    for c, a_s, a_e, a_parts in read_bed(p.a):
        if c not in B_by_chrom or not B_by_chrom[c]:
            out = a_parts + empty_b
            if p.d: out.append('-1')
            print(format_record(out))
            continue

        b_list = B_by_chrom[c]
        min_dist = float('inf')
