            for i, col in enumerate(c_cols):
                cur_vals[i].append(parts[col])

    if cur_g is not None:
        out = cur_g.copy()
        for i, op in enumerate(ops):
            out.append(agg_op(cur_vals[i], op))
        print(format_record(out))

