    G = read_genome(p.g)
    chroms = list(G.keys())
    for c, s, e, parts in read_bed(p.i):
        length = e - s
        if not chroms: continue
        rnd_c = random.choice(chroms)
        size = G[rnd_c]
        if size < length: continue
        rnd_s = random.randint(0, size - length)
