    elif cmd == 'slop': pass
    elif cmd == 'subtract': cmd_subtract(args)
    elif cmd == 'jaccard': cmd_jaccard(args)
    elif cmd == 'genomecov': cmd_genomecov(args)
    elif cmd == 'groupby': cmd_groupby(args)
    elif cmd == 'shuffle': cmd_shuffle(args)

if __name__ == '__main__': main()
