    for c, s, e, _ in read_bed(p.i):
        if c in cov:
            for i in range(max(0, s), min(e, G[c])): cov[c][i] += 1

    if p.bg:
        for c, size in G.items():
            if size == 0: continue
            cur_val = cov[c][0]
            cur_s = 0
            for i in range(1, size):
                if cov[c][i] != cur_val:
                    if cur_val > 0: print(f"{c}\t{cur_s}\t{i}\t{cur_val}")
                    cur_val = cov[c][i]
                    cur_s = i
            if cur_val > 0: print(f"{c}\t{cur_s}\t{size}\t{cur_val}")
    else:
        total_size = sum(G.values())
        total_counts = collections.defaultdict(int)
        for c, size in G.items():
            counts = collections.defaultdict(int)
            for val in cov[c]:
                counts[val] += 1
                total_counts[val] += 1
            for depth in sorted(counts.keys()):
                print(f"{c}\t{depth}\t{counts[depth]}\t{size}\t{counts[depth]/size:g}")
        for depth in sorted(total_counts.keys()):
            print(f"genome\t{depth}\t{total_counts[depth]}\t{total_size}\t{total_counts[depth]/total_size:g}")

