#!/usr/bin/env python3
import sys, gzip, collections, random, math, argparse

def open_file(f):
    if f == '-': return sys.stdin
    if f.endswith('.gz'): return gzip.open(f, 'rt')
    return open(f, 'r')

def read_bed(f):
    for line in open_file(f):
        if not line.strip() or line.startswith('#') or line.startswith('track') or line.startswith('browser'): continue
        parts = line.rstrip('\n').split('\t')
        if len(parts) >= 3:
            yield parts[0], int(parts[1]), int(parts[2]), parts

def read_genome(f):
    g = collections.OrderedDict()
    for line in open_file(f):
        if not line.strip(): continue
        p = line.strip().split()
        g[p[0]] = int(p[1])
    return g

def merge_intervals(intervals):
    if not intervals: return []
    intervals.sort(key=lambda x: (x[0], x[1]))
    res = []
    cur_s, cur_e = intervals[0]
    for s, e in intervals[1:]:
        if s <= cur_e: cur_e = max(cur_e, e)
        else:
            res.append((cur_s, cur_e))
            cur_s, cur_e = s, e
    res.append((cur_s, cur_e))
    return res

def format_record(parts):
    return '\t'.join(str(p) for p in parts)

def agg_op(vals, op):
    if op == 'count': return str(len(vals))
    if op == 'sum': return str(sum(float(v) for v in vals if v.replace('.','',1).isdigit()))
    if op == 'min': return str(min(float(v) for v in vals if v.replace('.','',1).isdigit()))
    if op == 'max': return str(max(float(v) for v in vals if v.replace('.','',1).isdigit()))
    if op == 'mean': return str(sum(float(v) for v in vals if v.replace('.','',1).isdigit()) / len(vals))
    if op == 'collapse': return ','.join(vals)
    return ','.join(vals)

def cmd_intersect(args):
    parser = argparse.ArgumentParser()
    parser.add_argument('-a', required=True)
    parser.add_argument('-b', nargs='+', required=True)
    parser.add_argument('-wa', action='store_true')
    parser.add_argument('-wb', action='store_true')
    parser.add_argument('-c', action='store_true')
    parser.add_argument('-v', action='store_true')
    parser.add_argument('-u', action='store_true')
    parser.add_argument('-wo', action='store_true')
    parser.add_argument('-f', type=float, default=1e-9)
    parser.add_argument('-r', action='store_true')
    parser.add_argument('-sorted', action='store_true')
    parser.add_argument('-names', nargs='*')
    p, _ = parser.parse_known_args(args)

    B_by_chrom = collections.defaultdict(list)
    for i, b_file in enumerate(p.b):
        name = p.names[i] if p.names and i < len(p.names) else None
        for c, s, e, parts in read_bed(b_file):
            B_by_chrom[c].append((s, e, parts, name))

    for c in B_by_chrom:
        B_by_chrom[c].sort(key=lambda x: x[0])

    for c, a_s, a_e, a_parts in read_bed(p.a):
        overlaps = []
        if c in B_by_chrom:
            for b_s, b_e, b_parts, b_name in B_by_chrom[c]:
                if b_s >= a_e: break
                if b_e <= a_s: continue
                o_s = max(a_s, b_s)
                o_e = min(a_e, b_e)
                if o_s < o_e:
                    o_len = o_e - o_s
                    a_len = a_e - a_s
                    b_len = b_e - b_s
                    f_a = o_len / a_len if a_len > 0 else 0
                    if f_a >= p.f:
                        if p.r:
                            f_b = o_len / b_len if b_len > 0 else 0
                            if f_b >= p.f:
                                overlaps.append((o_s, o_e, b_parts, o_len, b_name))
                        else:
                            overlaps.append((o_s, o_e, b_parts, o_len, b_name))

        if p.c:
            print(f"{format_record(a_parts)}\t{len(overlaps)}")
        elif p.v:
            if not overlaps: print(format_record(a_parts))
        elif p.u:
            if overlaps: print(format_record(a_parts))
        else:
            if not overlaps: continue
            for o_s, o_e, b_parts, o_len, b_name in overlaps:
                out = []
                if p.wa and p.wb: out = a_parts + b_parts
                elif p.wa: out = a_parts
                elif p.wb: out = [c, o_s, o_e] + a_parts[3:] + b_parts
                elif p.wo: out = a_parts + b_parts + [o_len]
                else: out = [c, o_s, o_e] + a_parts[3:]
                print(format_record(out))

def cmd_merge(args):
    parser = argparse.ArgumentParser()
