        for s, e, parts in recs[1:]:
            if s <= cur_e + p.d:
                cur_e = max(cur_e, e)
                for i, col in enumerate(cols):
                    cur_cols[i].append(parts[col] if col < len(parts) else '.')
            else:
                out = [c, cur_s, cur_e]
                for i, op in enumerate(ops): out.append(agg_op(cur_cols[i], op))
