def cmd_closest(args):
    parser = argparse.ArgumentParser()
    parser.add_argument('-a', required=True)
    parser.add_argument('-b', required=True)
    parser.add_argument('-d', action='store_true')
    p, _ = parser.parse_known_args(args)

    B_by_chrom = collections.defaultdict(list)
    for c, s, e, parts in read_bed(p.b):
        B_by_chrom[c].append((s, e, parts))
    for c in B_by_chrom:
        B_by_chrom[c].sort(key=lambda x: x[0])

    b_len = 0
    for c in B_by_chrom:
        if B_by_chrom[c]:
            b_len = len(B_by_chrom[c][0][2])
            break
    empty_b = ['.'] * b_len if b_len > 0 else ['.', '-1', '-1']
    if empty_b[:3] == ['.', '.', '.']:
        empty_b[1] = '-1'
        empty_b[2] = '-1'

    for c, a_s, a_e, a_parts in read_bed(p.a):
        if c not in B_by_chrom or not B_by_chrom[c]:
            out = a_parts + empty_b
            if p.d: out.append('-1')
            print(format_record(out))
            continue

        b_list = B_by_chrom[c]
        min_dist = float('inf')
        closest_bs = []
        for b_s, b_e, b_parts in b_list:
            dist = max(0, a_s - b_e + 1, b_s - a_e + 1)
            if dist < min_dist:
                min_dist = dist
                closest_bs = [b_parts]
            elif dist == min_dist:
                closest_bs.append(b_parts)

        for b_parts in closest_bs:
            out = a_parts + b_parts
            if p.d: out.append(str(min_dist))
            print(format_record(out))

def cmd_makewindows(args):
