            print(format_record(parts))
            continue
        pieces = [(a_s, a_e)]
        for b_s, b_e in B_by_chrom[c]:
            new_pieces = []
            for ps, pe in pieces:
                o_s = max(ps, b_s)
                o_e = min(pe, b_e)
                if o_s < o_e:
                    if ps < o_s: new_pieces.append((ps, o_s))
                    if o_e < pe: new_pieces.append((o_e, pe))
                else:
                    new_pieces.append((ps, pe))
            pieces = new_pieces
        for ps, pe in pieces:
            print(format_record([c, ps, pe] + parts[3:]))

def cmd_jaccard(args):
    parser = argparse.ArgumentParser()
    parser.add_argument('-a', required=True)
    parser.add_argument('-b', required=True)
    p, _ = parser.parse_known_args(args)
    A_by_chrom = collections.defaultdict(list)
    for c, s, e, _ in read_bed(p.a): A_by_chrom[c].append((s, e))
    B_by_chrom = collections.defaultdict(list)
    for c, s, e, _ in read_bed(p.b): B_by_chrom[c].append((s, e))

    inter_len = 0
    union_len = 0
    n_inter = 0
    for c in set(A_by_chrom) | set(B_by_chrom):
        a_merged = merge_intervals(A_by_chrom[c])
        b_merged = merge_intervals(B_by_chrom[c])
        union_len += sum(e - s for s, e in a_merged) + sum(e - s for s, e in b_merged)
        for a_s, a_e in a_merged:
            for b_s, b_e in b_merged:
                o_s = max(a_s, b_s)
                o_e = min(a_e, b_e)
                if o_s < o_e:
                    inter_len += o_e - o_s
                    n_inter += 1
    union_len -= inter_len
    jaccard = inter_len / union_len if union_len > 0 else 0
    print("intersection\tunion\tjaccard\tn_intersections")
    print(f"{inter_len}\t{union_len}\t{jaccard:g}\t{n_inter}")

